function selectPiece(i,focus=false){tabButtons.forEach((tab,n)=>{tab.setAttribute('aria-selected',String(n===i));tab.tabIndex=n===i?0:-1;});const text=$('#prose');if(text)text.textContent=prose[i];const panel=$('#writing-panel');if(panel)panel.setAttribute('aria-labelledby',tabButtons[i]?.id||'tab-0');if($('#piece-room'))$('#piece-room').textContent=pieceMeta[i][0];if($('#piece-mood'))$('#piece-mood').textContent=pieceMeta[i][1];if(focus)tabButtons[i]?.focus();}
