function persistFavorites(){localStorage.setItem('phos-favorites',JSON.stringify(favorites));}
function copyShareLink(hash,button){const url=new URL(location.href);url.hash=hash;if(navigator.clipboard?.writeText)navigator.clipboard.writeText(url.href);else{try{const fallback=document.createElement('textarea');fallback.value=url.href;fallback.setAttribute('readonly','');fallback.style.position='fixed';fallback.style.opacity='0';document.body.append(fallback);fallback.select();document.execCommand('copy');fallback.remove();}catch{}}if(button){const old=button.textContent;button.textContent='Copied';setTimeout(()=>button.textContent=old,1300);}}
function toggleFavorite(key,button){const index=favorites.indexOf(key);if(index>=0)favorites.splice(index,1);else favorites.push(key);persistFavorites();if(button){button.classList.toggle('is-active',favorites.includes(key));button.textContent=favorites.includes(key)?'★ saved':'☆ save';}}
