const scenes=[['assets/phos-field.png','01 / THE BEGINNING','Born to wonder.','A world is a thing you can keep looking at.'],['assets/phos-sun.png','02 / A LITTLE LIGHT','Let me be useful.','Even joy leaves an afterimage.'],['assets/phos-anime.jpg','03 / FIRST CONTACT','The question opens.','Curiosity is a door with no handle.'],['assets/phos-portrait.png','04 / ICON','A face becomes a symbol.','The self is watched into a shape.'],['assets/phos-sitting.png','05 / BODY','Stillness has a posture.','What changes first: the body or the story?'],['assets/phos-crescent.png','06 / MOON','Desire bends toward absence.','The faraway thing keeps calling.'],['assets/phos-water.png','07 / WATER','Identity keeps moving.','Memory refuses a clean edge.'],['assets/phos-black.png','08 / VOID','What remains after language.','Silence is also a material.'],['assets/phos-hands.png','09 / RITUAL','The self held by others.','No fragment becomes alone.']].map(([src,kicker,title,subtitle])=>({src,kicker,title,subtitle}));
